class Solution {
public:
    long long power(long long b, long long e, long long mod) {
        long long r = 1; b %= mod;
        while (e > 0) {
            if (e & 1) r = r * b % mod;
            b = b * b % mod;
            e >>= 1;
        }
        return r;
    }
    int sumKDigitNumbers(int l, int r, int k) {
        const long long MOD = 1e9 + 7;
        long long m = r - l + 1;
        long long inv9 = power(9, MOD - 2, MOD);
        long long S = (long long)(l + r) * m / 2 % MOD;
        long long term = power(m, k - 1, MOD);
        long long rep = (power(10, k, MOD) - 1 + MOD) % MOD * inv9 % MOD;
        return S * term % MOD * rep % MOD;
    }
};

